+ const g07Directory=path.join(os.tmpdir(),'geometry-tests');fs.mkdirSync(g07Directory,{recursive:true});
+ const g07Bytes=Buffer.from(await read(`Array.from(window.__generationBytes)`));
+ fs.writeFileSync(path.join(g07Directory,'assembly-generation-g07-before.gcanvas'),g07Bytes);
+ fs.writeFileSync(path.join(g07Directory,'assembly-generation-g07-before.json'),JSON.stringify(saved,null,2)+'\n');
+ check('G07 未完成實例草稿保存第8版',saved.format==='geometry-canvas/8'&&saved.drafts.some(d=>d.kind==='instance'&&d.data.members[0].guideId===0),saved);
  await read(`(async()=>{await ReferenceWorkspace.importBytes(window.__generationBytes,'生成重開.gcanvas');await renderObjects();})()`);check('G07 保存重開原生來源映射幾何精確一致',same((await state()).instances[0],changed));
